def apply_theme(app: QApplication, palette: Palette) -> None:
    """Install the Qt palette + stylesheet for one of our themes."""
    app.setStyle(QStyleFactory.create("Fusion"))

    q = QPalette()
    q.setColor(QPalette.Window, p_c(palette.window))
    q.setColor(QPalette.WindowText, p_c(palette.text))
    q.setColor(QPalette.Base, p_c(palette.surface))
    q.setColor(QPalette.AlternateBase, p_c(palette.surface_alt))
    q.setColor(QPalette.Text, p_c(palette.text))
    q.setColor(QPalette.Button, p_c(palette.surface_alt))
    q.setColor(QPalette.ButtonText, p_c(palette.text))
    q.setColor(QPalette.Highlight, p_c(palette.accent))
    q.setColor(QPalette.HighlightedText, p_c(palette.accent_text))
    q.setColor(QPalette.ToolTipBase, p_c(palette.surface))
    q.setColor(QPalette.ToolTipText, p_c(palette.text))
    q.setColor(QPalette.PlaceholderText, p_c(palette.text_dim))
    q.setColor(QPalette.Disabled, QPalette.Text, p_c(palette.text_dim))
    q.setColor(QPalette.Disabled, QPalette.ButtonText, p_c(palette.text_dim))
    q.setColor(QPalette.Disabled, QPalette.WindowText, p_c(palette.text_dim))
    app.setPalette(q)
    app.setStyleSheet(base_qss(palette) + table_qss(palette) + component_qss(palette))


def p_c(hex_color: str) -> QColor:
    return QColor(hex_color)

"""
Tiny JSON HTTP client built on urllib (zero dependencies).
Handles retries, exponential backoff, 429/5xx and pretty error extraction.
"""

from __future__ import annotations

import json
import time
import urllib.error
import urllib.parse
import urllib.request
from typing import Any, Mapping

USER_AGENT = "maplead/1.0 (python-urllib)"
DEFAULT_TIMEOUT = 45


class ApiError(RuntimeError):
    def __init__(self, message: str, status: int | None = None,
                 provider: str = "", payload: Any = None):
        super().__init__(message)
        self.message = message
        self.status = status
        self.provider = provider
        self.payload = payload

    def __str__(self) -> str:  # pragma: no cover
        if self.provider:
            return f"[{self.provider}] {self.message}"
        return self.message


class RateLimiter:
    """Simple minimum-interval throttle (per provider)."""

    def __init__(self, per_second: float = 5.0):
        self.min_interval = 1.0 / per_second if per_second > 0 else 0.0
        self._last = 0.0

    def wait(self) -> None:
        if self.min_interval <= 0:
            return
        delta = time.time() - self._last
        if delta < self.min_interval:
            time.sleep(self.min_interval - delta)
        self._last = time.time()


def _extract_error(body: bytes, status: int) -> str:
    text = ""
    try:
        text = body.decode("utf-8", "replace")
    except Exception:
        return f"HTTP {status}"
    try:
        data = json.loads(text)
    except Exception:
        text = " ".join(text.split())[:300]
        return f"HTTP {status}: {text}" if text else f"HTTP {status}"
    if isinstance(data, Mapping):
        err = data.get("error")
        if isinstance(err, Mapping):
            msg = err.get("message") or err.get("status") or json.dumps(err)[:300]
            return f"{msg} (HTTP {status})"
        if isinstance(err, str):
            return f"{err} (HTTP {status})"
        for key in ("message", "detail", "info", "error_message", "status_message", "status"):
            if key in data and isinstance(data[key], (str, int)):
                return f"{data[key]} (HTTP {status})"
        tasks = data.get("tasks")
        if isinstance(tasks, list) and tasks:
            t = tasks[0]
            if isinstance(t, Mapping):
                emsg = t.get("status_message")
                if emsg:
                    return f"{emsg} (HTTP {status})"
    if isinstance(data, list) and data:
        return f"{str(data[0])[:280]} (HTTP {status})"
    return f"HTTP {status}: {text[:280]}"


def request_json(method: str, url: str, *,
                 params: Mapping[str, Any] | None = None,
                 body: Any = None,
                 headers: Mapping[str, str] | None = None,
                 timeout: int = DEFAULT_TIMEOUT,
                 retries: int = 3,
                 backoff: float = 1.7,
                 provider: str = "") -> Any:
    """Perform an HTTP request and decode the JSON response."""
    if params:
        clean = {k: v for k, v in params.items() if v is not None and v != ""}
        if clean:
            url = url + ("&" if "?" in url else "?") + urllib.parse.urlencode(clean, doseq=True)

    data = None
    hdrs = {"User-Agent": USER_AGENT, "Accept": "application/json"}
    if body is not None:
        data = json.dumps(body).encode("utf-8")
        hdrs["Content-Type"] = "application/json"
    if headers:
        hdrs.update({k: v for k, v in headers.items() if v})

    last_err: Exception | None = None
    for attempt in range(retries + 1):
        req = urllib.request.Request(url, data=data, headers=hdrs, method=method.upper())
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                raw = resp.read()
                if not raw:
                    return {}
                try:
                    return json.loads(raw.decode("utf-8", "replace"))
                except json.JSONDecodeError:
                    return {"_raw": raw.decode("utf-8", "replace")[:20000]}
        except urllib.error.HTTPError as exc:
            raw = exc.read() if hasattr(exc, "read") else b""
            msg = _extract_error(raw, exc.code)
            if exc.code in (400, 401, 403, 404) and exc.code not in (429,):
                raise ApiError(msg, exc.code, provider, raw[:2000]) from None
            last_err = ApiError(msg, exc.code, provider, raw[:2000])
            retry_after = exc.headers.get("Retry-After") if exc.headers else None
            if retry_after and retry_after.isdigit():
                time.sleep(min(60, int(retry_after)))
        except urllib.error.URLError as exc:
            reason = getattr(exc, "reason", exc)
            last_err = ApiError(f"network error: {reason}", provider=provider)
        except (TimeoutError, OSError) as exc:
            last_err = ApiError(f"connection problem: {exc}", provider=provider)
        except KeyboardInterrupt:
            raise
        if attempt < retries:
            time.sleep(backoff ** attempt + 0.15 * attempt)

    assert last_err is not None
    raise last_err


def get_json(url: str, **kw) -> Any:
    return request_json("GET", url, **kw)


def post_json(url: str, **kw) -> Any:
    return request_json("POST", url, **kw)

"""
Where MAPLEAD keeps its configuration, API keys and exports.

XDG-aware so the GUI works from a read-only AppImage bundle:

    config  $XDG_CONFIG_HOME/maplead/.env      (keys, window geometry)
    data    $XDG_DATA_HOME/maplead/            (state, history)
    exports ~/Documents/maplead/               (lead files)

The CLI keeps preferring a legacy `.env` that sits next to the tool, so old
installs behave exactly as before; the GUI always uses the config dir.
"""

from __future__ import annotations

import os
import re
from typing import Dict, List, Optional

APP_ID = "maplead"
APP_TITLE = "MAPLEAD"
PACKAGE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


# --------------------------------------------------------------------------- #
# directories
# --------------------------------------------------------------------------- #

def _base_dir(env_var: str, fallback: str) -> str:
    base = os.environ.get(env_var, "").strip()
    if base and os.path.isabs(base):
        return base
    return os.path.join(os.path.expanduser("~"), fallback)


def config_dir() -> str:
    return os.path.join(_base_dir("XDG_CONFIG_HOME", ".config"), APP_ID)


def data_dir() -> str:
    return os.path.join(_base_dir("XDG_DATA_HOME", ".local/share"), APP_ID)


def _user_dirs(key: str) -> Optional[str]:
    """Resolve an XDG user-dirs key ($HOME/Documents, ...) when published."""
    for candidate in (os.path.join(_base_dir("XDG_CONFIG_HOME", ".config"), "user-dirs.dirs"),):
        try:
            with open(candidate, "r", encoding="utf-8") as fh:
                for line in fh:
                    m = re.match(rf'\s*{key}\s*=\s*"(.*)"\s*$', line)
                    if m:
                        raw = m.group(1)
                        raw = raw.replace("$HOME", os.path.expanduser("~"))
                        return raw if os.path.isabs(raw) else None
        except OSError:
            continue
    return None


def documents_dir() -> str:
    return _user_dirs("XDG_DOCUMENTS_DIR") or os.path.join(os.path.expanduser("~"), "Documents")


def default_export_dir() -> str:
    return os.path.join(documents_dir(), APP_ID)


def ensure_dir(path: str) -> str:
    try:
        os.makedirs(path, exist_ok=True)
    except OSError:
        pass
    return path


# --------------------------------------------------------------------------- #
# env / key storage
# --------------------------------------------------------------------------- #

def user_env_file() -> str:
    return os.path.join(config_dir(), ".env")


def legacy_env_file() -> str:
    """The `.env` next to the source tree (CLI behaviour, kept for compat)."""
    return os.path.join(PACKAGE_DIR, ".env")


def env_file() -> str:
    """Where new keys get written: keep honouring an existing legacy `.env`."""
    legacy = legacy_env_file()
    if os.path.exists(legacy):
        return legacy
    return user_env_file()


def env_candidates() -> List[str]:
    """Every place a key may live, most specific first."""
    order = [env_file(), user_env_file(), legacy_env_file(),
             os.path.join(os.getcwd(), ".env")]
    seen, out = set(), []
    for path in order:
        real = os.path.abspath(path)
        if real not in seen:
            seen.add(real)
            out.append(path)
    return out


def load_env(path: Optional[str] = None) -> str:
    """Load KEY=VALUE pairs without clobbering the real environment.

    Returns the file that was used (or would be written for new keys).
    """
    used = env_file()
    for candidate in env_candidates():
        if not os.path.exists(candidate):
            continue
        used = candidate
        try:
            with open(candidate, "r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line or line.startswith("#") or "=" not in line:
                        continue
                    key, _, val = line.partition("=")
                    key = key.strip()
                    val = val.strip().strip("'\"")
                    if key and not os.environ.get(key):
                        os.environ[key] = val
        except OSError:
            pass
        break
    return used


def read_env_file(path: Optional[str] = None) -> Dict[str, str]:
    """Parse a .env file without exporting anything to os.environ."""
    target = path or env_file()
    values: Dict[str, str] = {}
    try:
        with open(target, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, _, val = line.partition("=")
                values[key.strip()] = val.strip().strip("'\"")
    except OSError:
        pass
    return values


def save_env_key(key: str, value: str, path: Optional[str] = None) -> str:
    """Write KEY=VALUE into the env file, preserving comments and other keys."""
    target = path or env_file()
    lines: List[str] = []
    if os.path.exists(target):
        try:
            with open(target, "r", encoding="utf-8") as fh:
                lines = fh.read().splitlines()
        except OSError:
            lines = []
    replaced = False
    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith("#") or "=" not in stripped:
            continue
        if stripped.split("=", 1)[0].strip() == key:
            lines[i] = f"{key}={value}" if value else f"{key}="
            replaced = True
            break
    if not replaced:
        if lines and lines[-1].strip():
            lines.append("")
        lines.append(f"{key}={value}" if value else f"{key}=")
    parent = os.path.dirname(os.path.abspath(target))
    if parent:
        ensure_dir(parent)
    with open(target, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines).rstrip("\n") + "\n")
    try:
        os.chmod(target, 0o600)          # it holds secrets
    except OSError:
        pass
    os.environ[key] = value
    return target


def clear_env_key(key: str, path: Optional[str] = None) -> bool:
    target = path or env_file()
    if not os.path.exists(target):
        return False
    try:
        with open(target, "r", encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except OSError:
        return False
    hit = False
    for i, line in enumerate(lines):
        if "=" in line and not line.strip().startswith("#") \
                and line.split("=", 1)[0].strip() == key:
            lines[i] = f"{key}="
            hit = True
    if hit:
        try:
            with open(target, "w", encoding="utf-8") as fh:
                fh.write("\n".join(lines).rstrip("\n") + "\n")
        except OSError:
            return False
    os.environ.pop(key, None)
    return hit


# --------------------------------------------------------------------------- #
# GUI state
# --------------------------------------------------------------------------- #

def state_file(name: str) -> str:
    return os.path.join(ensure_dir(data_dir()), name)
